@page "/settings"
@using sv_9103abc4e95f43ebb982f9bdf32d3954.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (ActiveSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (Profile is not null)
                {
                    <div class="form-group avatar-group">
                        <div class="avatar-preview">
                            <img src="@EditDisplayAvatarUrl" alt="Avatar" />
                        </div>
                        <div class="avatar-url">
                            <label>Avatar URL</label>
                            <input type="text" @bind="EditDisplayAvatarUrl" />
                        </div>
                    </div>
                    <div class="form-group">
                        <label>Display Name</label>
                        <input type="text" @bind="EditDisplayName" />
                    </div>
                    <div class="form-group">
                        <label>Email</label>
                        <input type="email" @bind="EditEmail" />
                    </div>
                    <div class="form-group">
                        <label>Bio</label>
                        <textarea rows="4" @bind="EditBio"></textarea>
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                        <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (NotifPrefs is not null)
                {
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Email Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="NotifEmailEnabled" />
                                <span class="slider"></span>
                            </label>
                        </label>
                        <label class="toggle-label">
                            <span>Push Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="NotifPushEnabled" />
                                <span class="slider"></span>
                            </label>
                        </label>
                        <label class="toggle-label">
                            <span>Weekly Digest</span>
                            <label class="switch">
                                <input type="checkbox" @bind="NotifWeeklyDigest" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in AllChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox" checked="@IsChannelMuted(channel)"
                                       @onchange="e => ToggleChannelMute(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        }
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (Security is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(PasswordPanelOpen ? "▾" : "▸")</span>
                        </button>
                        @if (PasswordPanelOpen)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label>Current Password</label>
                                    <input type="password" @bind="CurrentPassword" />
                                </div>
                                <div class="form-group">
                                    <label>New Password</label>
                                    <input type="password" @bind="NewPassword" />
                                </div>
                                <div class="form-group">
                                    <label>Confirm New Password</label>
                                    <input type="password" @bind="ConfirmPassword" />
                                </div>
                                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="toggle-group" style="margin-top: 1.5rem;">
                        <label class="toggle-label">
                            <span>
                                Two-Factor Authentication
                                <span class="status-indicator @(TwoFactorEnabled ? "status-on" : "status-off")">
                                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                                </span>
                            </span>
                            <label class="switch">
                                <input type="checkbox" @bind="TwoFactorEnabled" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    @if (Security.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != CurrentSessionId)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>

                    @if (ShowRevokeDialog)
                    {
                        <div class="dialog-overlay" @onclick="CancelRevoke">
                            <div class="dialog" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke?.Device</strong> in <strong>@SessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (Appearance is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Light" checked="@(AppTheme == "Light")" @onchange='() => AppTheme = "Light"' /> Light
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Dark" checked="@(AppTheme == "Dark")" @onchange='() => AppTheme = "Dark"' /> Dark
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="System" checked="@(AppTheme == "System")" @onchange='() => AppTheme = "System"' /> System
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="fontsize" value="Small" checked="@(AppFontSize == "Small")" @onchange='() => AppFontSize = "Small"' /> Small
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontsize" value="Medium" checked="@(AppFontSize == "Medium")" @onchange='() => AppFontSize = "Medium"' /> Medium
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontsize" value="Large" checked="@(AppFontSize == "Large")" @onchange='() => AppFontSize = "Large"' /> Large
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Language</label>
                        <select @bind="AppLanguage">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>

                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Compact Mode</span>
                            <label class="switch">
                                <input type="checkbox" @bind="AppCompactMode" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Live Preview</h3>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">Preview Header</div>
                        <div class="preview-body">
                            <p>This is how your content will look with the selected settings.</p>
                            <p>Theme: <strong>@AppTheme</strong> | Font: <strong>@AppFontSize</strong> | Language: <strong>@AppLanguage</strong></p>
                        </div>
                        <div class="preview-sidebar">Sidebar</div>
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
            </section>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile
    private UserProfile? Profile { get; set; }
    private string EditDisplayName { get; set; } = "";
    private string EditEmail { get; set; } = "";
    private string EditDisplayAvatarUrl { get; set; } = "";
    private string EditBio { get; set; } = "";

    // Notifications
    private NotificationPrefs? NotifPrefs { get; set; }
    private bool NotifEmailEnabled { get; set; }
    private bool NotifPushEnabled { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private readonly List<string> AllChannels = new() { "general", "marketing", "engineering", "design", "announcements", "random" };

    // Security
    private SecuritySettings? Security { get; set; }
    private bool PasswordPanelOpen { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private bool TwoFactorEnabled { get; set; }
    private string CurrentSessionId => Security?.Sessions.FirstOrDefault()?.Id ?? "";
    private bool ShowRevokeDialog { get; set; }
    private ActiveSession? SessionToRevoke { get; set; }

    // Appearance
    private AppearanceSettings? Appearance { get; set; }
    private string AppTheme { get; set; } = "Light";
    private string AppFontSize { get; set; } = "Medium";
    private string AppLanguage { get; set; } = "English";
    private bool AppCompactMode { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section) => ActiveSection = section;

    // Profile methods
    private async Task LoadProfile()
    {
        Profile = await SettingsService.GetProfileAsync();
        PopulateProfileFields();
    }

    private void PopulateProfileFields()
    {
        if (Profile is null) return;
        EditDisplayName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditDisplayAvatarUrl = Profile.AvatarUrl;
        EditBio = Profile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(EditDisplayName, EditEmail, EditDisplayAvatarUrl, EditBio);
        await SettingsService.SaveProfileAsync(updated);
        Profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        PopulateProfileFields();
        ShowToast("Changes discarded.", "info");
    }

    // Notification methods
    private async Task LoadNotifications()
    {
        NotifPrefs = await SettingsService.GetNotificationPrefsAsync();
        NotifEmailEnabled = NotifPrefs.EmailNotifications;
        NotifPushEnabled = NotifPrefs.PushNotifications;
        NotifWeeklyDigest = NotifPrefs.WeeklyDigest;
        MutedChannels = new List<string>(NotifPrefs.MutedChannels);
    }

    private bool IsChannelMuted(string channel) => MutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

