                {
                    <div class="form-group avatar-group">
                        <div class="avatar-preview">
                            <img src="@EditDisplayAvatarUrl" alt="Avatar" />
                        </div>
                        <div class="avatar-url">
                            <label>Avatar URL</label>
                            <input type="text" @bind="EditDisplayAvatarUrl" />
                        </div>
                    </div>
                    <div class="form-group">
                        <label>Display Name</label>
                        <input type="text" @bind="EditDisplayName" />
                    </div>
                    <div class="form-group">
                        <label>Email</label>
                        <input type="email" @bind="EditEmail" />
                    </div>
                    <div class="form-group">
                        <label>Bio</label>
                        <textarea rows="4" @bind="EditBio"></textarea>
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                        <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (NotifPrefs is not null)
                {
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Email Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="NotifEmailEnabled" />
                                <span class="slider"></span>
                            </label>
                        </label>
                        <label class="toggle-label">
                            <span>Push Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="NotifPushEnabled" />
                                <span class="slider"></span>
                            </label>
                        </label>
                        <label class="toggle-label">
                            <span>Weekly Digest</span>
                            <label class="switch">
                                <input type="checkbox" @bind="NotifWeeklyDigest" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in AllChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox" checked="@IsChannelMuted(channel)"
                                       @onchange="e => ToggleChannelMute(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
