                                <div class="form-group">
                                    <label>Current Password</label>
                                    <input type="password" @bind="CurrentPassword" />
                                </div>
                                <div class="form-group">
                                    <label>New Password</label>
                                    <input type="password" @bind="NewPassword" />
                                </div>
                                <div class="form-group">
                                    <label>Confirm New Password</label>
                                    <input type="password" @bind="ConfirmPassword" />
                                </div>
                                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="toggle-group" style="margin-top: 1.5rem;">
                        <label class="toggle-label">
                            <span>
                                Two-Factor Authentication
                                <span class="status-indicator @(TwoFactorEnabled ? "status-on" : "status-off")">
                                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                                </span>
                            </span>
                            <label class="switch">
                                <input type="checkbox" @bind="TwoFactorEnabled" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    @if (Security.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != CurrentSessionId)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>

                    @if (ShowRevokeDialog)
                    {
                        <div class="dialog-overlay" @onclick="CancelRevoke">
                            <div class="dialog" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke?.Device</strong> in <strong>@SessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (Appearance is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Light" checked="@(AppTheme == "Light")" @onchange='() => AppTheme = "Light"' /> Light
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Dark" checked="@(AppTheme == "Dark")" @onchange='() => AppTheme = "Dark"' /> Dark
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="System" checked="@(AppTheme == "System")" @onchange='() => AppTheme = "System"' /> System
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="fontsize" value="Small" checked="@(AppFontSize == "Small")" @onchange='() => AppFontSize = "Small"' /> Small
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontsize" value="Medium" checked="@(AppFontSize == "Medium")" @onchange='() => AppFontSize = "Medium"' /> Medium
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontsize" value="Large" checked="@(AppFontSize == "Large")" @onchange='() => AppFontSize = "Large"' /> Large
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Language</label>
                        <select @bind="AppLanguage">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>

                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Compact Mode</span>
                            <label class="switch">
                                <input type="checkbox" @bind="AppCompactMode" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Live Preview</h3>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">Preview Header</div>
                        <div class="preview-body">
                            <p>This is how your content will look with the selected settings.</p>
                            <p>Theme: <strong>@AppTheme</strong> | Font: <strong>@AppFontSize</strong> | Language: <strong>@AppLanguage</strong></p>
                        </div>
                        <div class="preview-sidebar">Sidebar</div>
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
            </section>
        }
    </main>
</div>

