@code {
    private string ActiveSection { get; set; } = "Profile";
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile
    private UserProfile? Profile { get; set; }
    private string EditDisplayName { get; set; } = "";
    private string EditEmail { get; set; } = "";
    private string EditDisplayAvatarUrl { get; set; } = "";
    private string EditBio { get; set; } = "";

    // Notifications
    private NotificationPrefs? NotifPrefs { get; set; }
    private bool NotifEmailEnabled { get; set; }
    private bool NotifPushEnabled { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private readonly List<string> AllChannels = new() { "general", "marketing", "engineering", "design", "announcements", "random" };

    // Security
    private SecuritySettings? Security { get; set; }
    private bool PasswordPanelOpen { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private bool TwoFactorEnabled { get; set; }
    private string CurrentSessionId => Security?.Sessions.FirstOrDefault()?.Id ?? "";
    private bool ShowRevokeDialog { get; set; }
    private ActiveSession? SessionToRevoke { get; set; }

    // Appearance
    private AppearanceSettings? Appearance { get; set; }
    private string AppTheme { get; set; } = "Light";
    private string AppFontSize { get; set; } = "Medium";
    private string AppLanguage { get; set; } = "English";
    private bool AppCompactMode { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section) => ActiveSection = section;

    // Profile methods
    private async Task LoadProfile()
    {
        Profile = await SettingsService.GetProfileAsync();
        PopulateProfileFields();
    }

    private void PopulateProfileFields()
    {
        if (Profile is null) return;
        EditDisplayName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditDisplayAvatarUrl = Profile.AvatarUrl;
        EditBio = Profile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(EditDisplayName, EditEmail, EditDisplayAvatarUrl, EditBio);
        await SettingsService.SaveProfileAsync(updated);
        Profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        PopulateProfileFields();
        ShowToast("Changes discarded.", "info");
    }

    // Notification methods
    private async Task LoadNotifications()
    {
        NotifPrefs = await SettingsService.GetNotificationPrefsAsync();
        NotifEmailEnabled = NotifPrefs.EmailNotifications;
        NotifPushEnabled = NotifPrefs.PushNotifications;
        NotifWeeklyDigest = NotifPrefs.WeeklyDigest;
        MutedChannels = new List<string>(NotifPrefs.MutedChannels);
    }

    private bool IsChannelMuted(string channel) => MutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(NotifEmailEnabled, NotifPushEnabled, NotifWeeklyDigest, new List<string>(MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        NotifPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        Security = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = Security.TwoFactorEnabled;
    }

    private void TogglePasswordPanel() => PasswordPanelOpen = !PasswordPanelOpen;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        PasswordPanelOpen = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeDialog = true;
    }

    private void CancelRevoke()
    {
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (SessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(SessionToRevoke.Id);
            await LoadSecurity();
            ShowToast($"Session on {SessionToRevoke.Device} revoked.", "success");
        }
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        Appearance = await SettingsService.GetAppearanceAsync();
        AppTheme = Appearance.Theme;
        AppFontSize = Appearance.FontSize;
        AppLanguage = Appearance.Language;
        AppCompactMode = Appearance.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{AppTheme.ToLower()} preview-font-{AppFontSize.ToLower()}";
        if (AppCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(AppTheme, AppFontSize, AppLanguage, AppCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        Appearance = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
    }

    private void DismissToast() => ToastMessage = null;
}
